import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
class Solution {
    public ListListInteger combinationSum2(int[] candidates, int target) {
        int[] a = candidates.clone();
        Arrays.sort(a);
        ListListInteger answer = new ArrayList();
        dfs(a, 0, target, new ArrayList(), answer);
        return answer;
    }
    private void dfs(int[] a, int start, int remain, ListInteger path,
                     ListListInteger answer) {
        if (remain == 0) {
            answer.add(new ArrayList(path));
            return;
        }
        for (int i = start; i  a.length; i++) {
            if (i  start && a[i] == a[i - 1]) continue;
            if (a[i]  remain) break;
            path.add(a[i]);
            dfs(a, i + 1, remain - a[i], path, answer);
            path.remove(path.size() - 1);
        }
    }
}


