class Solution {
    public boolean exist(char[][] board, String word) {
        if (word.isEmpty()) return true;
        if (board.length == 0 || board[0].length == 0) return false;
        boolean[][] used = new boolean[board.length][board[0].length];
        for (int r = 0; r  board.length; r++) {
            for (int c = 0; c  board[0].length; c++) {
                if (dfs(board, word, r, c, 0, used)) return true;
            }
        }
        return false;
    }
    private boolean dfs(char[][] b, String w, int r, int c,
                        int k, boolean[][] used) {
        if (r  0 || r = b.length || c  0 || c = b[0].length
                || used[r][c] || b[r][c] != w.charAt(k)) return false;
        if (k == w.length() - 1) return true;
        used[r][c] = true;
        boolean found = dfs(b, w, r + 1, c, k + 1, used)
                || dfs(b, w, r - 1, c, k + 1, used)
                || dfs(b, w, r, c + 1, k + 1, used)
                || dfs(b, w, r, c - 1, k + 1, used);
        used[r][c] = false;
        return found;
    }
}


 语句逐项看：word.isEmpty() 检查长度0；charAt(k) 取正在匹配的字符；一串 || 从左到右短路，所以只有坐标合法才会读 used[r][c]；先保存 found，再恢复 used，保证成功和失败两种退出都恢复路径。boolean[][] 默认 false，无需 Arrays.fill。此实现不改变 board。设单词长度 L，宽松时间 O(RC·4^L)，利用不能立即走回上格可写 O(RC·3^L) 的同阶指数界（首步有4个方向）；额外空间 O(RC+L)。可加 LRC 提前返回和字符频次不足剪枝。 

