import java.util.ArrayList;
import java.util.List;
class Solution {
    public ListListString partition(String s) {
        int n = s.length();
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i = 0; i--) {
            for (int j = i; j  n; j++) {
                pal[i][j] = s.charAt(i) == s.charAt(j)
                        && (j - i  2 || pal[i + 1][j - 1]);
            }
        }
        ListListString answer = new ArrayList();
        dfs(s, 0, pal, new ArrayList(), answer);
        return answer;
    }
    private void dfs(String s, int start, boolean[][] pal,
                     ListString path, ListListString answer) {
        if (start == s.length()) {
            answer.add(new ArrayList(path));
            return;
        }
        for (int end = start; end  s.length(); end++) {
            if (!pal[start][end]) continue;
            path.add(s.substring(start, end + 1));
            dfs(s, end + 1, pal, path, answer);
            path.remove(path.size() - 1);
        }
    }
}


 substring(start,end+1) 左闭右开，pal 却使用两端闭区间，所以要 +1。new ArrayList(path) 复制容器，否则所有答案会随着同一个 path 回退而被清空；String 不可变，所以不必复制字符串内容。remove(path.size()-1) 参数是 int，下标删除尾部，不是按对象值删除。j-i2 || ... 的短路避免长度1/2时访问不存在的内部区间。课件第99页变量 len 表示 j−i，并非实际长度，实际长度为 len+1。最坏全相同字符有 2^(n−1) 种划分；预处理 O(n²)，生成结果约 O(n2^n)，额外工作空间 O(n²+n)，输出另计。 

