import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
class Solution {
    public ListListInteger levelOrder(TreeNode root) {
        ListListInteger answer = new ArrayList();
        if (root == null) return answer;
        QueueTreeNode queue = new ArrayDeque();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            ListInteger level = new ArrayList(size);
            for (int i = 0; i  size; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            answer.add(level);
        }
        return answer;
    }
}


 new ArrayList(size) 指初始容量，列表仍为空，不能随即get(0)；本代码用add逐个写入。poll删除队首并返回节点；非空条件和固定循环次数保证此处非null。每层new一个level，因此不用额外复制就能保存；复用同一列表再clear会破坏已保存结果。时间O(N)，队列O(W)，输出O(N)，W为最大层宽。空树返回[]，不能向ArrayDeque加入null。课件第22页哨兵Java版未先判断空根，可能不断处理null；本实现补齐。 

