import java.util.Collections;
import java.util.List;
import java.util.Queue;
class Solution {
    public ListListInteger zigzagLevelOrder(TreeNode root) {
        ListListInteger answer = new ArrayList();
        if (root == null) return answer;
        QueueTreeNode queue = new ArrayDeque();
        queue.offer(root);
        boolean leftToRight = true;
        while (!queue.isEmpty()) {
            int size = queue.size();
            ListInteger level = new ArrayList(size);
            for (int i = 0; i  size; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            if (!leftToRight) Collections.reverse(level);
            answer.add(level);
            leftToRight = !leftToRight;
        }
        return answer;
    }
}


 Collections.reverse原地反转列表，单层O(k)，所有层的k相加等于N，所以课件提出的“每层反转很费时吗”答案是：增加线性常数工作，总时间仍O(N)。!leftToRight 每层切换一次。双栈也可实现：弹栈的次序与压入次序相反，因此按层交替压左/右，但更容易弄反。工作空间O(W)，结果O(N)，不是因为反转就变O(N²)。 

