 java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
class Solution {
    public ListListString findLadders(String beginWord, String endWord,
                                          ListString wordList) {
        ListListString answer = new ArrayList();
        SetString words = new HashSet(wordList);
        if (!words.contains(endWord)) return answer;
        MapString, Integer dist = new HashMap();
        MapString, ListString parents = new HashMap();
        QueueString queue = new ArrayDeque();
        queue.offer(beginWord);
        dist.put(beginWord, 0);
        int targetDistance = Integer.MAX_VALUE;
        while (!queue.isEmpty()) {
            String word = queue.poll();
            int nextDistance = dist.get(word) + 1;
            if (nextDistance  targetDistance) continue;
            char[] chars = word.toCharArray();
            for (int i = 0; i  chars.length; i++) {
                char old = chars[i];
                for (char c = 'a'; c = 'z'; c++) {
                    if (c == old) continue;
                    chars[i] = c;
                    String next = new String(chars);
                    if (!words.contains(next)) continue;
                    if (!dist.containsKey(next)) {
                        dist.put(next, nextDistance);
                        queue.offer(next);
                    }
                    if (dist.get(next) == nextDistance) {
                        parents.computeIfAbsent(next, key - new ArrayList()).add(word);
                        if (next.equals(endWord)) targetDistance = nextDistance;
                    }
                }
                chars[i] = old;
            }
        }
        if (dist.containsKey(endWord)) {
            build(endWord, beginWord, parents, new ArrayList(), answer);
        }
        return answer;
    }
    private void build(String word, String begin, MapString, ListString parents,
                       ListString reversePath, ListListString answer) {
        reversePath.add(word);
        if (word.equals(begin)) {
            ListString path = new ArrayList(reversePath);
            Collections.reverse(path);
            answer.add(path);
        } else {
            for (String parent : parents.get(word)) {
                build(parent, begin, parents, reversePath, answer);
            }
        }
        reversePath.remove(reversePath.size() - 1);
    }
}


 MapString,Integer把词映射到距离，get自动拆箱后与int比较；computeIfAbsent(next,key - new ArrayList())是Java8 API，缺键时创建列表，有键则返回已有列表，接着add记录另一个父节点。lambda参数key在这里不参与列表构造，只满足函数接口签名。反向DFS每一步距离严格减少，不会有环；到begin时复制reversePath、再反转副本，不能原地反转共享path。得到一条后撤销当前词，再试另一个父亲。 

 设最短路径数P，每条含D个词，前驱边数E。BFS约O(26NL²)，重建与复制O(PD)，额外索引空间O(NL+E)，输出O(PD)个词引用；不能忽略输出可能指数增长。end缺席返回[]；不可达也返回[]。课件第98页wordList/wordSet名称混用与方法参数类型不一致，直接拼接片段可能编译失败；此处统一words集合。若BFS把整条路径都入队，同一前缀会复制很多次，前驱DAG通常更省空间。 

