import java.util.;
class FileSystem {
    private static class Node {
        boolean file;
        StringBuilder content = new StringBuilder();
        TreeMapString, Node children = new TreeMap();
    }
    private final Node root = new Node();
    public FileSystem() { }
    private Node walk(String path, boolean create) {
        Node cur = root;
        for (String part : path.split("/")) {
            if (part.isEmpty()) continue;
            if (create) cur.children.putIfAbsent(part, new Node());
            cur = cur.children.get(part);
            if (cur == null) throw new IllegalArgumentException("Missing path");
        }
        return cur;
    }
    public ListString ls(String path) {
        Node node = walk(path, false);
        if (node.file) {
            return Collections.singletonList(path.substring(path.lastIndexOf('/') + 1));
        }
        return new ArrayList(node.children.keySet());
    }
    public void mkdir(String path) {
        walk(path, true);
    }
    public void addContentToFile(String filePath, String content) {
        Node node = walk(filePath, true);
        node.file = true;
        node.content.append(content);
    }
    public String readContentFromFile(String filePath) {
        return walk(filePath, false).content.toString();
    }
}

 逐词 DFS 会反复搜索相同前缀。先把所有词建成 Trie，在网格里走一个字符，Trie 也同时走一条边；不存在对应孩子，说明词典里没有任何词能从这个前缀继续，立即剪枝。一个 Trie 结点的 word 保存完整单词，命中时直接收集，不再拼接字符串。 

 1. 在所有格子枚举起点，因为词可以从任意位置开始。
2. 越界或本路径已访问则返回。
3. 查询 Trie 对应字符分支，不存在则返回。
4. 若 word 非空，加入答案，并清空 word 去重。
5. 临时把网格字符改成 ，递归四邻居。
6. 回溯时恢复原字符，供其他路径使用。 

 java
import java.util.;
class Solution {
    private static class Node {
        Node[] next = new Node[26];
        String word;
    }
    public ListString findWords(char[][] board, String[] words) {
        Node root = new Node();
        for (String word : words) {
            Node cur = root;
            for (char ch : word.toCharArray()) {
                int i = ch - 'a';
                if (cur.next[i] == null) cur.next[i] = new Node();
                cur = cur.next[i];
            }
            cur.word = word;
        }
        ListString result = new ArrayList();
        for (int r = 0; r  board.length; r++) {
            for (int c = 0; c  board[0].length; c++) {
                dfs(board, r, c, root, result);
            }
        }
        return result;
    }
    private void dfs(char[][] board, int r, int c, Node parent, ListString out) {
        if (r  0 || r = board.length || c  0 || c = board[0].length) return;
        char ch = board[r][c];
        if (ch == '') return;
        Node node = parent.next[ch - 'a'];
        if (node == null) return;
        if (node.word != null) {
            out.add(node.word);
            node.word = null;
        }
        board[r][c] = '';
        dfs(board, r + 1, c, node, out);
        dfs(board, r - 1, c, node, out);
        dfs(board, r, c + 1, node, out);
        dfs(board, r, c - 1, node, out);
        board[r][c] = ch;
    }
}


