class Solution {
    public int numTrees(int n) {
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int size = 1; size = n; size++) {
            for (int root = 1; root = size; root++) {
                dp[size] += dp[root - 1]  dp[size - root];
            }
        }
        return (int) dp[n];
    }
}


