import java.util.;
class Solution {
    public ListTreeNode generateTrees(int n) {
        if (n == 0) return new ArrayList();
        return build(1, n);
    }
    private ListTreeNode build(int lo, int hi) {
        ListTreeNode out = new ArrayList();
        if (lo  hi) {
            out.add(null);
            return out;
        }
        for (int value = lo; value = hi; value++) {
            ListTreeNode lefts = build(lo, value - 1);
            ListTreeNode rights = build(value + 1, hi);
            for (TreeNode left : lefts) {
                for (TreeNode right : rights) {
                    TreeNode root = new TreeNode(value);
                    root.left = copy(left);
                    root.right = copy(right);
                    out.add(root);
                }
            }
        }
        return out;
    }
    private TreeNode copy(TreeNode node) {
        if (node == null) return null;
        TreeNode out = new TreeNode(node.val);
        out.left = copy(node.left);
        out.right = copy(node.right);
        return out;
    }
}


