import java.util.;
class Codec {
    public String serialize(TreeNode root) {
        StringBuilder out = new StringBuilder();
        encode(root, out);
        return out.toString();
    }
    private void encode(TreeNode node, StringBuilder out) {
        if (node == null) {
            out.append(",");
            return;
        }
        out.append(node.val).append(',');
        encode(node.left, out);
        encode(node.right, out);
    }
    public TreeNode deserialize(String data) {
        DequeString tokens = new ArrayDeque(Arrays.asList(data.split(",")));
        return decode(tokens);
    }
    private TreeNode decode(DequeString tokens) {
        String token = tokens.removeFirst();
        if (token.equals("")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(token));
        node.left = decode(tokens);
        node.right = decode(tokens);
        return node;
    }
}


