import java.util.;
class Solution {
    public int calculate(String s) {
        DequeInteger saved = new ArrayDeque();
        int result = 0, sign = 1;
        for (int i = 0; i  s.length(); i++) {
            char c = s.charAt(i);
            if (c = '0' && c = '9') {
                int value = 0;
                while (i  s.length() && s.charAt(i) = '0'
                        && s.charAt(i) = '9') {
                    value = value  10 + s.charAt(i) - '0';
                    i++;
                }
                i--;
                result += sign  value;
            } else if (c == '+') {
                sign = 1;
            } else if (c == '-') {
                sign = -1;
            } else if (c == '(') {
                saved.push(result);
                saved.push(sign);
                result = 0;
                sign = 1;
            } else if (c == ')') {
                int outerSign = saved.pop();
                int outerResult = saved.pop();
                result = outerResult + outerSign  result;
            }
        }
        return result;
    }
}


