import java.util.;
class Solution {
    public int leastBricks(ListListInteger wall) {
        MapInteger, Integer edges = new HashMap();
        int most = 0;
        for (ListInteger row : wall) {
            int position = 0;
            for (int i = 0; i  row.size() - 1; i++) {
                position += row.get(i);
                int count = edges.getOrDefault(position, 0) + 1;
                edges.put(position, count);
                most = Math.max(most, count);
            }
        }
        return wall.size() - most;
    }
}


