class Solution {
    public int subarraysDivByK(int[] nums, int k) {
        int[] frequency = new int[k];
        frequency[0] = 1;
        int remainder = 0, answer = 0;
        for (int x : nums) {
            remainder = ((remainder + x) % k + k) % k;
            answer += frequency[remainder];
            frequency[remainder]++;
        }
        return answer;
    }
}


