import java.util.;
// LeetCode 提供 ListNode：int val; ListNode next; ListNode(int val)
class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        PriorityQueueListNode heap = new PriorityQueue((a, b) - Integer.compare(a.val, b.val));
        for (ListNode head : lists) if (head != null) heap.offer(head);
        ListNode dummy = new ListNode(0), tail = dummy;
        while (!heap.isEmpty()) {
            ListNode node = heap.poll();
            ListNode next = node.next;
            tail.next = node;
            tail = node;
            if (next != null) heap.offer(next);
        }
        return dummy.next;
    }
}


