import java.util.;
class Solution {
    public void wiggleSort(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int small = (nums.length - 1) / 2, large = nums.length - 1;
        for (int i = 0; i  nums.length; i++) {
            nums[i] = (i & 1) == 0 ? sorted[small--] : sorted[large--];
        }
    }
}


