import java.util.;
class Solution {
    public int findTheLongestSubstring(String s) {
        int[] first = new int[32];
        Arrays.fill(first, -2);
        first[0] = -1;
        int mask = 0, best = 0;
        for (int i = 0; i  s.length(); i++) {
            int bit = "aeiou".indexOf(s.charAt(i));
            if (bit = 0) mask ^= 1  bit;
            if (first[mask] == -2) first[mask] = i;
            else best = Math.max(best, i - first[mask]);
        }
        return best;
    }
}


