import java.util.;
class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, ListListString people) {
        MapString, Integer index = new HashMap();
        for (int i = 0; i  req_skills.length; i++) index.put(req_skills[i], i);
        MapInteger, ListInteger dp = new HashMap();
        dp.put(0, new ArrayListInteger());
        for (int person = 0; person  people.size(); person++) {
            int skills = 0;
            for (String skill : people.get(person)) {
                Integer bit = index.get(skill);
                if (bit != null) skills |= 1  bit;
            }
            if (skills == 0) continue;
            MapInteger, ListInteger next = new HashMap(dp);
            for (Map.EntryInteger, ListInteger entry : dp.entrySet()) {
                int combined = entry.getKey() | skills;
                ListInteger team = entry.getValue();
                if (!next.containsKey(combined) || team.size() + 1  next.get(combined).size()) {
                    ListInteger candidate = new ArrayList(team);
                    candidate.add(person);
                    next.put(combined, candidate);
                }
            }
            dp = next;
        }
        ListInteger best = dp.get((1  req_skills.length) - 1);
        int[] answer = new int[best.size()];
        for (int i = 0; i  answer.length; i++) answer[i] = best.get(i);
        return answer;
    }
}


 new HashMap(dp) 只浅复制键值关联；因为从不原地修改旧的 team，这样安全。新候选必须 new ArrayList(team) 后再 add，否则不同状态会意外共享并改变成员列表。(1m)-1 生成低m位全1，依赖m足够小；[官方约束](https://leetcode.com/problems/smallest-sufficient-team/)限定技能数m≤16、人数p≤60，技能状态最多65536，支持int掩码。最优队伍可选至多m人，故复制列表版本时间 O(p·m·2^m+技能输入长度)、空间 O(m·2^m)，p为人数；只记人数与前驱可进一步省复制成本。测试一个人全会、人人只有一技、有重复技能、无相关技能的人、存在多个同样最优队伍。 

