import java.util.;
class Solution {
    public ListListInteger subsets(int[] nums) {
        ListListInteger answer = new ArrayList();
        int limit = 1  nums.length;
        for (int mask = 0; mask  limit; mask++) {
            ListInteger subset = new ArrayList();
            for (int i = 0; i  nums.length; i++) if ((mask & (1  i)) != 0) subset.add(nums[i]);
            answer.add(subset);
        }
        return answer;
    }
    public ListListInteger combine(int n, int k) {
        ListListInteger answer = new ArrayList();
        for (int mask = 0; mask  (1  n); mask++) {
            if (Integer.bitCount(mask) != k) continue;
            ListInteger combination = new ArrayList();
            for (int i = 0; i  n; i++) if ((mask & (1  i)) != 0) combination.add(i + 1);
            answer.add(combination);
        }
        return answer;
    }
}


 Integer.bitCount(mask) 返回1的数量；测试 (mask&(1i))!=0，不能一律等于1，因为高位掩码结果可能是2、4、8。每次创建新List，不能复用同一对象存入所有答案。这里限定 n≤20 等可枚举规模，并且必须 n31 才能安全用正 int 上界；n增加会指数爆炸，不是换long即可解决。全部子集时间/输出空间 O(n2^n)，固定k版仍扫描2^n状态，回溯仅生成 C(n,k) 个组合通常更合适。测试空数组产生一个空集、k=0产生一个空组合、k=n仅一个全集。

