import java.util.concurrent.atomic.AtomicInteger;

public class CounterDemo {
    private static int lockedCount;
    private static final Object LOCK = new Object();
    private static final AtomicInteger atomicCount = new AtomicInteger();
    public static void main(String[] args) throws InterruptedException {
        Thread[] workers = new Thread[4];
        for (int i = 0; i  workers.length; i++) {
            workers[i] = new Thread(() - {
                for (int j = 0; j  10000; j++) {
                    synchronized (LOCK) { lockedCount++; }
                    atomicCount.incrementAndGet();
                }
            });
            workers[i].start();
        }
        for (Thread worker : workers) worker.join();
        System.out.println(lockedCount); // 40000
        System.out.println(atomicCount.get()); // 40000
    }
}


 所有线程必须锁同一个 LOCK，锁不同对象不能保护同一 count。LOCK 用 private final 避免外部锁住它或替换引用。AtomicInteger.incrementAndGet 是原子增量并返回新值，不能改成 get()+set() 两个调用。join 建立工作线程完成到主线程后续读取的可见性；这里只在全部 join 后读 lockedCount，所以无需再用锁读最终结果。

