import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.LongAdder;

public class PoolDemo {
    public static void main(String[] args) throws Exception {
        MapString, LongAdder counts = new ConcurrentHashMap();
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 4, 30, TimeUnit.SECONDS,
            new ArrayBlockingQueue(8),
            new ThreadPoolExecutor.CallerRunsPolicy());
        ListFuture? tasks = new ArrayList();
        try {
            for (int i = 0; i  20; i++) {
                tasks.add(pool.submit(() - {
                    for (int j = 0; j  1000; j++)
                        counts.computeIfAbsent("java", key - new LongAdder()).increment();
                }));
            }
            for (Future? task : tasks) task.get();
            System.out.println(counts.get("java").sum()); // 20000
        } finally {
            pool.shutdown();
            if (!pool.awaitTermination(10, TimeUnit.SECONDS)) pool.shutdownNow();
        }
    }
}


 ArrayBlockingQueue 容量8限制排队任务数。CallerRunsPolicy 在运行中的线程池饱和时让提交者执行任务，减缓继续提交的速度；它不是所有场景通用选择，提交线程不能阻塞时要换策略。submit 返回 Future，get 等待完成并暴露 ExecutionException；不能只提交任务后忽略失败。 

 Future? 是未知结果类型，因为这些任务不需要返回值。LongAdder 把竞争分散到多个内部计数单元，适合统计；并发执行时 sum 不是原子快照。本例在全部 Future.get 完成后求和，所以结果准确。computeIfAbsent 的创建函数应短小，不在里面执行网络 IO；只创建计数器，累加在外面进行。shutdown 停止接受新任务并处理已有任务，shutdownNow 尝试中断，任务仍需响应中断。 

